<template><section class="view on"><div class="grid g2col reveal" style="grid-template-columns:1.4fr 1fr"><div class="card glass"><div class="ch"><h3>Uploaded materials</h3></div><TutorEmptyState v-if="!resources.length" title="No materials"/><div v-for="r in resources" :key="r.resourceId" class="row"><div class="av" :style="{background:r.gradient}"><svg width="16" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" v-html="r.icon"></svg></div><div class="g1"><div class="t">{{r.title}}</div><div class="s">{{r.description}}</div></div><a v-if="r.resourceLink" :href="r.resourceLink.startsWith('http')?r.resourceLink:`http://localhost:5000${r.resourceLink}`" target="_blank" class="btn sm">Open</a><button class="btn sm" type="button" @click="remove(r.resourceId)">Delete</button></div></div><div class="card glass"><div class="ch"><h3>Upload material</h3></div><label class="lab">Session</label><select v-model="sessionId" class="field" style="margin-bottom:12px"><option value="">Choose session</option><option v-for="s in sessions" :key="s.id" :value="s.id">{{s.subject}} · {{s.date}} · {{s.time}}</option></select><label class="lab">Title</label><input v-model="title" class="field" style="margin-bottom:12px" placeholder="Algebra Notes"><label class="lab">File</label><input ref="file" type="file" class="field" style="margin-bottom:12px" @change="selected=$event.target.files[0]"><label class="lab">or Resource Link</label><input v-model="link" class="field" style="margin-bottom:12px" placeholder="https://..."><button class="btn grad magnetic" :disabled="uploading" type="button" style="width:100%;justify-content:center" @click="upload">{{uploading?'Uploading...':'Upload & notify students'}}</button><p v-if="message" class="eyebrow" style="margin-top:10px">{{message}}</p></div></div></section></template>
<script setup>
import {ref} from 'vue';import TutorEmptyState from '../../components/tutor/TutorEmptyState.vue';import {tutorApi} from '../../services/tutorApi'
const props=defineProps({resources:{type:Array,required:true},sessions:{type:Array,default:()=>[]}});const emit=defineEmits(['toast']);const sessionId=ref(''),title=ref(''),link=ref(''),selected=ref(null),uploading=ref(false),message=ref('')
async function upload(){try{if(!sessionId.value)throw new Error('Choose a session');if(!title.value)throw new Error('Enter a title');if(!selected.value&&!link.value)throw new Error('Choose a file or provide a link');const fd=new FormData();fd.append('session_id',sessionId.value);fd.append('title',title.value);fd.append('resource_link',link.value);if(selected.value)fd.append('file',selected.value);uploading.value=true;await tutorApi.uploadMaterial(fd);message.value='Material uploaded';emit('toast','Material uploaded to the database');location.reload()}catch(e){message.value=e.message}finally{uploading.value=false}}
async function remove(id){try{await tutorApi.deleteMaterial(id);emit('toast','Material deleted');location.reload()}catch(e){emit('toast',e.message)}}
</script>
